const fs = require('fs');
const path = require('path');

const root = 'E:/AI-System 3.0';

// Check .opencode directory
const opencodeDir = path.join(root, '.opencode');
console.log('.opencode exists:', fs.existsSync(opencodeDir));

if (fs.existsSync(opencodeDir)) {
  console.log('.opencode contents:', fs.readdirSync(opencodeDir, { recursive: true }));
} else {
  console.log('.opencode directory DOES NOT EXIST');
}

// Check for any opencode config files
const configs = ['opencode.json', '.opencode.json', 'opencode.config.json'];
configs.forEach(c => {
  const p = path.join(root, c);
  console.log(`${c} exists:`, fs.existsSync(p));
});

// Check scripts/verify.sh
const verifyScript = path.join(root, 'scripts', 'verify.sh');
console.log('scripts/verify.sh exists:', fs.existsSync(verifyScript));
if (fs.existsSync(verifyScript)) {
  console.log('scripts/verify.sh content:');
  console.log(fs.readFileSync(verifyScript, 'utf8'));
}

// Check OMNI-INBOX.md for the GCR entry
const inbox = path.join(root, 'OMNI-INBOX.md');
if (fs.existsSync(inbox)) {
  const content = fs.readFileSync(inbox, 'utf8');
  const lines = content.split('\n');
  const gcrLines = lines.filter(l => l.toLowerCase().includes('gcr') || l.toLowerCase().includes('auto-review'));
  console.log('GCR/Auto-review lines in OMNI-INBOX.md:');
  gcrLines.forEach(l => console.log('  ', l));
}

// Check for any plugin/hook directories
const possibleDirs = [
  '.opencode/plugins',
  '.opencode/hooks',
  '.claude/hooks',
  '.github/workflows'
];
possibleDirs.forEach(d => {
  const p = path.join(root, d);
  console.log(`${d} exists:`, fs.existsSync(p));
  if (fs.existsSync(p)) {
    console.log(`  contents:`, fs.readdirSync(p, { recursive: true }));
  }
});

