const fs = require('fs');
const path = require('path');

// Pfad zu opencode.json
const opencodeJsonPath = path.join(__dirname, 'E:/AI-System 3.0/opencode.json');

// Lesen der aktuellen opencode.json
let opencodeJson = JSON.parse(fs.readFileSync(opencodeJsonPath, 'utf8'));

// Hinzufügen der plugins-Array, falls nicht vorhanden
if (!opencodeJson.plugins) {
    opencodeJson.plugins = [];
}

// Hinzufügen der Plugins
opencodeJson.plugins.push(
    path.join(__dirname, '.opencode/plugins/auto-review.js')
);
opencodeJson.plugins.push(
    path.join(__dirname, '.opencode/plugins/codeguardian/index.ts')
);

// Schreiben der aktualisierten opencode.json
fs.writeFileSync(opencodeJsonPath, JSON.stringify(opencodeJson, null, 2), 'utf8');

// Pfad zu auto-review.js
const autoReviewJsPath = path.join(__dirname, '.opencode/plugins/auto-review.js');

// Lesen der aktuellen auto-review.js
let autoReviewJs = fs.readFileSync(autoReviewJsPath, 'utf8');

// Ersetzen des Pfades in auto-review.js
autoReviewJs = autoReviewJs.replace(
    'bash projects/json2csv/verify.sh',
    'bash scripts/verify.sh'
);

// Schreiben der aktualisierten auto-review.js
fs.writeFileSync(autoReviewJsPath, autoReviewJs, 'utf8');

// Ausgabe der Änderungen
