import { AutoReview } from './orchestrator.js'; // Oder Logik aus auto-review.js kopieren
import { $ } from 'zx'; // OpenCode Umgebung nutzt zx-Stil für Befehle

// Simulierter Event für den manuellen Trigger
const manualTrigger = async () => {
  console.log("[Orchestrator] Manuelle Pipeline gestartet...");

  // Kopie der Logik aus auto-review.js ohne Event-Abhängigkeit
  const diff = (await $`git status --porcelain`.text()).trim();
  if (!diff) {
    console.log("[Orchestrator] Keine Änderungen, Abbruch.");
    return;
  }

  console.log("[Orchestrator] Änderungen erkannt, starte Verify & Review...");
  // ... hier die Logik zum Aufruf von verify.sh und Reviewer
};

manualTrigger().catch(console.error);

import { execSync } from "node:child_process";

const runReview = async () => {
  console.log("[Orchestrator] Manuelle Pipeline gestartet...");

  // Diff prüfen
  const diff = execSync("git status --porcelain").toString().trim();
  if (!diff) {
    console.log("[Orchestrator] Keine Änderungen, Abbruch.");
    return;
  }

  console.log("[Orchestrator] Änderungen erkannt:");
  console.log(diff);

  // verify.sh ausführen
  try {
    console.log("[Orchestrator] Starte scripts/verify.sh...");
    const verifyOutput = execSync("bash scripts/verify.sh").toString();
    console.log(verifyOutput);
    console.log("[Orchestrator] Verifizierung erfolgreich.");
  } catch (e) {
    console.error("[Orchestrator] Verifizierung fehlgeschlagen:", e.stdout.toString());
    process.exit(1);
  }
};

runReview().catch(console.error);

