import { execSync } from "node:child_process";
import { writeFile, mkdir } from "node:fs/promises";
import path from "node:path";

const REVIEWER_MODEL = "ollama/codellama:latest";
const VAULT = "E:/AI-System 3.0/codeguardian";

const callReviewer = async (client, sessionID, prompt) => {
  const res = await client.session.prompt({
    path: { id: sessionID },
    body: {
      model: REVIEWER_MODEL,
      agent: "reviewer",
      parts: [{ type: "text", text: prompt }],
    },
  });
  return (res.data?.parts ?? []).filter(p => p.type === "text").map(p => p.text).join("\n");
};

const runReview = async (client) => {
  console.log("[Orchestrator] Manuelle Pipeline gestartet...");

  // Diff prüfen
  const diff = execSync("git status --porcelain").toString().trim();
  if (!diff) {
    console.log("[Orchestrator] Keine Änderungen, Abbruch.");
    return;
  }

  console.log("[Orchestrator] Änderungen erkannt:");
  console.log(diff);

  // verify.sh ausführen (Git Bash auf Windows)
  try {
    console.log("[Orchestrator] Starte scripts/verify.sh...");
    const bashPath = "C:/Program Files/Git/bin/bash.exe";
    const verifyOutput = execSync(`"${bashPath}" scripts/verify.sh`).toString();
    console.log(verifyOutput);
    console.log("[Orchestrator] Verifizierung erfolgreich.");
  } catch (e) {
    console.error("[Orchestrator] Verifizierung fehlgeschlagen:", e.stdout.toString());
    process.exit(1);
  }

  // Reviewer-Agent aufrufen
  const sessionID = crypto.randomUUID();
  const reviewPrompt = `\n\n### Review-Aufgabe\n\n1. Prüfe die Doctest-Abdeckung (verify.sh-Ausgabe).\n2. Vergleiche Schritt-Kommentare im Code mit der Ausführung.\n3. Prüfe Edge Cases und Fehlerbehandlung.\n4. Schreibe eine Obsidian-Note mit YAML-Frontmatter:\n\n\(\n---\nprojekt: codeguardian\ndatum: ${new Date().toISOString().replace(/[:.]/g, "-")}\nstatus: bestanden | fehlgeschlagen\nabweichungen: <zahl>\ndurchlauf: 1\ndateien:\n  - projects/csv2json/src/csv2json.py\ntags: [codeguardian, review]\n---\n\n### Prüfung codeguardian — ${new Date().toISOString().replace(/[:.]/g, "-")} — Lauf 1\n\n\(\n## Ergebnis\n\n\(\n## Schritt-Abgleich\n\n\(\n## Input/Output\n\n\(\n## verify.sh\n\n\(\n\(\n\(\n## Verknüpfungen\n\n\(\n\(\n\)`;
  const reviewResult = await callReviewer(client, sessionID, reviewPrompt);

  // Note im Vault speichern
  const notePath = path.join(VAULT, `PRUEFUNG-csv2json-${new Date().toISOString().replace(/[:.]/g, "-")}.md`);
  await mkdir(path.dirname(notePath), { recursive: true });
  await writeFile(notePath, reviewResult);
  console.log("[Orchestrator] Review-Note gespeichert:", notePath);
};

runReview().catch(console.error);

