72: // ─── Ollama Direct Call (keine SDK erforderlich) ─────────────────────────────
73: const callOllama = async (prompt) => {
74:   const modelName = REVIEWER_MODEL.replace("ollama/", ""); // "codellama:latest"
75:   const body = JSON.stringify({
76:     model: modelName,
77:     prompt: prompt,
78:     stream: false,
79:     options: { temperature: 0.2, num_predict: 2000 },
80:   });
81:   console.log(`[Ollama] POST http://127.0.0.1:11434/api/generate  model=${modelName}`);
82:   const res = await fetch("http://127.0.0.1:11434/api/generate", {
83:     method: "POST",
84:     headers: { "Content-Type": "application/json" },
85:     body,
86:     signal: AbortSignal.timeout(120_000),
87:   });
88:   if (!res.ok) throw new Error(`Ollama HTTP ${res.status}: ${await res.text()}`);
89:   const data = await res.json();
90:   return data.response?.trim() || "(leere Antwort)";
91: };
92: 
93: // ─── Hauptpipeline ────────────────────────────────────────────────────────────
94: export const runReview = async () => {
95:   log("=== Manuelle Codeguardian-Pipeline gestartet ===");
96:   const start = Date.now();
97: 
98:   // 1. Diff prüfen
99:   const changedFiles = getChangedPythonFiles();
100:   if (changedFiles.length === 0) {
101:     log("Keine Python-Änderungen erkannt – Abbruch.");
102:     return { skipped: true, reason: "no-changes" };
103:   }
104:   log(`Änderungen erkannt (${changedFiles.length} Dateien):`);
105:   changedFiles.forEach((f) => log(`  - ${f}`));
106: 
107:   // 2. verify.sh ausführen
108:   log("Starte scripts/verify.sh …");
109:   const verifyResult = runVerify();
110:   log(`verify.sh beendet — exit=${verifyResult.exitCode}, ok=${verifyResult.ok}`);
111:   if (verifyResult.stdout) console.log(verifyResult.stdout.slice(0, 1500));
112: 
113:   // 3. Reviewer prompt bauen
114:   const datum = new Date().toISOString().slice(0, 19).replace(/T/, "T");
115:   const filesList = changedFiles.map((f) => `  - ${f}`).join("\n");
116:   const statusLine = verifyResult.ok ? "bestanden" : "fehlgeschlagen";
117: 
118:   const reviewPrompt = `Du bist der Reviewer-Agent für die Codeguardian-Pipeline von AI-System 4.0.
119: 
120: ### Aufträge
121: 1. Prüfe Doctest-Abdeckung anhand des verify.sh-Outputs.
122: 2. Vergleiche Schritt-Kommentare im Code mit der Ausführung.
123: 3. Identifiziere Edge-Cases / Sicherheitsprobleme / missing type hints.
124: 4. Gib eine strukturierte Obsidian-Note zurück (exakt dieses Format, kein extra Text drumherum):
125: 
126: ---
127: typ: code-pruefung
128: projekt: codeguardian
129: datum: ${datum}
130: status: ${statusLine}
131: abweichungen: ${verifyResult.ok ? 0 : 1}
132: durchlauf: 1
133: dateien:
134: ${filesList}
135: tags: [codeguardian, review]
136: ---
137: 
138: # Prüfung codeguardian — ${datum} — Lauf 1
139: 
140: ## Ergebnis
141: ${verifyResult.ok ? "✅ **Bestanden** — " + verifyResult.stdout.match(/(\d+) passed/)?.[1] + " Tests erfolgreich." : "❌ **Fehlgeschlagen** — Exit-Code " + verifyResult.exitCode}
142: 
143: ## verify.sh
144: **Exit-Code:** ${verifyResult.exitCode}
145: \`\`\`
146: ${(verifyResult.stdout || "").slice(0, 1500)}
147: ${verifyResult.stderr ? "\nStderr:\n" + verifyResult.stderr.slice(0, 500) : ""}
148: \`\`\`
149: 
150: ## Verknüpfungen
151: - [[OMNI-INBOX]]
152: - [[Code-Prüfungen Übersicht]]
153: ---`;
154: 
155:   log("Starte Ollama Reviewer (Modell: " + REVIEWER_MODEL + ") …");
156:   let reviewResult;
157:   try {
158:     reviewResult = await callOllama(reviewPrompt);
159:   } catch (err) {
160:     log("Ollama-Fehler: " + err.message);
161:     reviewResult = `## Fehler\nOllama-Call fehlgeschlagen: ${err.message}\n\nReviewer konnte nicht ausgeführt werden.`;
162:   }
163:   log("Reviewer abgeschlossen (" + ((Date.now() - start) / 1000).toFixed(1) + "s)");
164: 
165:   // 4. Vault-Note schreiben
166:   const noteName = `PRUEFUNG-${datum.replace(/[:.]/g, "-")}.md`;
167:   const notePath = path.join(VAULT_DIR, noteName);
168:   await mkdir(VAULT_DIR, { recursive: true });
169:   const finalContent = `${reviewResult}\n\n---\n_Generiert durch manuellen Run vom ${new Date().toISOString()} | Session-ID: ${randomUUID()}_\n`;
170:   await writeFile(notePath, finalContent);
171:   log(`Vault-Note gespeichert: ${notePath}`);
172: 
173:   console.log(`\n✅ Pipeline fertig in ${(Date.now() - start) / 1000 | 0}s`);
174:   console.log(`📄 Note: ${notePath}`);
175:   return { ok: true, notePath, exitCode: verifyResult.exitCode, durationMs: Date.now() - start };
176: };
177: 
178: // CLI entry-point (direkter node-Aufruf → automatisch starten)
179: const scriptName = path.basename(process.argv[1] ?? "");
180: if (scriptName === "run-review.js") {
181:   runReview().catch((err) => {
182:     log("FATAL: " + err.message);
183:     console.error(err);
184:     process.exit(2);
185:   });
186: }

